package com.shopsphere.dao;
import com.shopsphere.model.Coupon;
import com.shopsphere.util.DBConnection;
import java.sql.*;
import java.util.*;
public class CouponDAO {
    public Coupon findById(Integer id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM coupons WHERE id=?")) { p.setInt(1, id); try (ResultSet r = p.executeQuery()) { return r.next() ? map(r) : null; } } catch (SQLException e) { return null; } }
    public Coupon findByCode(String code) { if (code == null) return null; try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM coupons WHERE code=?")) { p.setString(1, code.trim().toUpperCase()); try (ResultSet r = p.executeQuery()) { return r.next() ? map(r) : null; } } catch (SQLException e) { return null; } }
    public List<Coupon> findAll() { List<Coupon> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT * FROM coupons ORDER BY id DESC"); ResultSet r = p.executeQuery()) { while (r.next()) l.add(map(r)); } catch (SQLException e) {} return l; }
    public boolean create(Coupon cp) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("INSERT INTO coupons (code,discount_type,discount_value,min_order_amount,usage_limit,times_used,expiry_date,status) VALUES (?,?,?,?,?,?,?,?)", Statement.RETURN_GENERATED_KEYS)) { p.setString(1, cp.getCode()); p.setString(2, cp.getDiscountType().name()); p.setBigDecimal(3, cp.getDiscountValue()); p.setBigDecimal(4, cp.getMinOrderAmount()); p.setInt(5, cp.getUsageLimit()); p.setInt(6, cp.getTimesUsed()); p.setDate(7, cp.getExpiryDate()); p.setString(8, cp.getStatus().name()); if (p.executeUpdate() > 0) { try (ResultSet k = p.getGeneratedKeys()) { if (k.next()) cp.setId(k.getInt(1)); } return true; } } catch (SQLException e) {} return false; }
    public boolean update(Coupon cp) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE coupons SET discount_type=?,discount_value=?,min_order_amount=?,usage_limit=?,expiry_date=?,status=? WHERE id=?")) { p.setString(1, cp.getDiscountType().name()); p.setBigDecimal(2, cp.getDiscountValue()); p.setBigDecimal(3, cp.getMinOrderAmount()); p.setInt(4, cp.getUsageLimit()); p.setDate(5, cp.getExpiryDate()); p.setString(6, cp.getStatus().name()); p.setInt(7, cp.getId()); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public boolean updateStatus(Integer id, Coupon.Status status) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE coupons SET status=? WHERE id=?")) { p.setString(1, status.name()); p.setInt(2, id); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    public boolean delete(Integer id) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("DELETE FROM coupons WHERE id=?")) { p.setInt(1, id); return p.executeUpdate() > 0; } catch (SQLException e) { return false; } }
    private Coupon map(ResultSet r) throws SQLException { Coupon cp = new Coupon(); cp.setId(r.getInt("id")); cp.setCode(r.getString("code")); cp.setDiscountType(Coupon.DiscountType.valueOf(r.getString("discount_type"))); cp.setDiscountValue(r.getBigDecimal("discount_value")); cp.setMinOrderAmount(r.getBigDecimal("min_order_amount")); cp.setUsageLimit(r.getInt("usage_limit")); cp.setTimesUsed(r.getInt("times_used")); cp.setExpiryDate(r.getDate("expiry_date")); cp.setStatus(Coupon.Status.valueOf(r.getString("status"))); return cp; }
}
